def reverse_order(%Ecto.Query{} = query) do
  order_bys = query.order_bys
  if Enum.empty?(order_bys) do
    schema = assert_schema!(query)
    pks = schema.__schema__(:primary_key)
    expr = for pk <- pks, do: {Enum.at([:asc, :desc], rem(Enum.count(pks) + 1, 2)), field(0, pk)}
